class OpResult(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    index: Annotated[int, Field(ge=0)]
    op: Literal[
        'move_rack', 'place_device', 'unplace_device', 'create_rack', 'update_fields'
    ]
    client_ref: str | None
    target: Annotated[OpTarget, Field(title='OpTarget')]
    status: Annotated[
        Literal['ok', 'no_change', 'error', 'skipped'],
        Field(
            description='skipped = not run because an earlier op failed during apply.'
        ),
    ]
    before: Annotated[
        dict[str, Any] | None,
        Field(
            description='The touched fields before (contract field names); null for create_rack.'
        ),
    ]
    after: Annotated[
        dict[str, Any] | None,
        Field(
            description='The touched fields after (predicted in preview, read back from NetBox after apply).'
        ),
    ]
    diff: list[FieldDiff]
    error: ErrorBody | None


